def backfill_account(apps, schema_editor):
    """المرتجعات القديمة اللي اتخصمت من الحساب: المبلغ كله على الحساب (عشان الأرصدة ما تتغيرش)"""
    from django.db.models import F, Sum
    SaleReturn = apps.get_model("trade", "SaleReturn")
    for r in SaleReturn.objects.filter(is_confirmed=True, refund_mode="account"):
        total = r.items.aggregate(s=Sum(F("quantity") * F("unit_refund")))["s"] or 0
        SaleReturn.objects.filter(pk=r.pk).update(account_amount=total)


Migration.operations.append(migrations.RunPython(backfill_account, migrations.RunPython.noop))
